from maya import cmds

for side in ("L_", "R_"):
    cmds.group(empty=True, name=side + "arm_grp")

for node in cmds.ls("*_grp"):
    cmds.rename(node, node.replace("_grp", "_offset"))
print(sorted(cmds.ls("*_offset")))  # ['L_arm_offset', 'R_arm_offset']

from maya import cmds
import functools

def one_undo(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        cmds.undoInfo(openChunk=True, chunkName=func.__name__)
        try:
            return func(*args, **kwargs)
        finally:
            cmds.undoInfo(closeChunk=True)
    return wrapper

@one_undo
def build():
    for i in range(3):
        cmds.spaceLocator(name="loc%d" % i)

cmds.undoInfo(state=True, infinity=True)
build()
print(len(cmds.ls("loc*", type="transform")))  # 3
cmds.undo()
print(len(cmds.ls("loc*", type="transform")))  # 0
